package com.fasterxml.jackson.databind.node;

import com.fasterxml.jackson.annotation.JsonAutoDetect;
import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.SerializerProvider;
import com.fasterxml.jackson.databind.jsontype.TypeSerializer;
import com.fasterxml.jackson.databind.node.JsonNodeFactory;
import java.io.*;
import java.io.IOException;
import java.math.*;
import java.math.BigDecimal;
import java.util.*;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collection;
import java.util.Iterator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class ObjectNode_equals_TriageGen0Test {

    private JsonNodeFactory factory;
    private ObjectNode node1;
    private ObjectNode node2;

    @Before
    public void setUp() {
        factory = JsonNodeFactory.instance;
        node1 = factory.objectNode();
        node2 = factory.objectNode();
    }

    @Test
    public void testEquals_Reflexive() {
        // if (o == this) return true;
        assertTrue("Object should be equal to itself", node1.equals(node1));
    }

    @Test
    public void testEquals_Null() {
        // if (o == null) return false;
        assertFalse("Object should not be equal to null", node1.equals(null));
    }

    @Test
    public void testEquals_DifferentType() {
        // if (o instanceof ObjectNode) ... return false;
        // Using a TextNode to test the 'instanceof' failure path
        JsonNode textNode = factory.textNode("test");
        assertFalse("ObjectNode should not be equal to a different JsonNode type", node1.equals(textNode));

        // Testing with a raw String
        assertFalse("ObjectNode should not be equal to a String", node1.equals("not a node"));
    }

    @Test
    public void testEquals_SameContent() {
        // Testing _childrenEqual(ObjectNode) logic via content equality
        node1.put("key1", "value1");
        node1.put("key2", 100);

        node2.put("key1", "value1");
        node2.put("key2", 100);

        assertTrue("Nodes with identical content should be equal", node1.equals(node2));
    }

    @Test
    public void testEquals_DifferentContent() {
        // Testing _childrenEqual(ObjectNode) returning false
        node1.put("key1", "value1");
        node2.put("key1", "different");

        assertFalse("Nodes with different content should not be equal", node1.equals(node2));
    }

    @Test
    public void testEquals_DifferentSize() {
        node1.put("key1", "value1");
        // node2 is empty
        assertFalse("Nodes with different number of fields should not be equal", node1.equals(node2));
    }

    @Test
    public void testEquals_NestedObjectEquality() {
        // Testing that equality holds deep into the tree
        ObjectNode child1 = factory.objectNode();
        child1.put("sub", 1);

        ObjectNode child2 = factory.objectNode();
        child2.put("sub", 1);

        node1.set<JsonNode>("child", child1);
        node2.set<JsonNode>("child", child2);

        assertTrue("Deeply nested identical objects should be equal", node1.equals(node2));

        node2.set<JsonNode>("child", factory.objectNode()); // change child2 to empty
        assertFalse("Nodes with different nested objects should not be equal", node1.equals(node2));
    }
}
